export function anchorsForDay(day) {
  const sharedHomestayDays = ['9/9', '9/10', '9/11'];
  return RESTAURANT_DATA.filter(anchor => anchor.date === day || (sharedHomestayDays.includes(day) && anchor.date === '9/9–9/11'));
}
